-- 📚 꼭집 주거 사전 — 갱신계약 소득초과 할증 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 3.0초 · 결과:
-- {"anns": 117, "by_std": {"국민임대": 61, "매입임대": 28, "전세임대": 4, "통합공공임대": 4, "행복주택": 18, "행복주택(신혼희망)": 2}, "ex": ["20652_1_서울특별시_영등포구", "2015122300020871", "2015122300020870", "2015122300020855"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where '갱신 할증'=cls),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='갱신 할증' group by 1)q),'ex',(select json_agg(i) from(select distinct announcement_id i from y where '갱신 할증'=cls order by 1 desc limit 4)q))j;
